<style lang="scss" scoped src="./table-block.scss"></style>

<script>
import { Vue, Prop, Component } from "vue-property-decorator";
import { IconShape } from "../icon/icon.constants";
import Table from "../table/table.vue";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import { has } from "../../util/has";
import Icon from "../icon/icon.vue";
import {
  TableCellSize,
  TableDataType,
  TableMode,
  TableModeValues
} from "../table/table.constants";
import { TableHeaderCellAlignment } from "../table-header-cell/table-header-cell.constants";
import { currencyFormat } from "../../util/currency-format";
import { TableBlockMode, TableBlockModeValues } from "./table-block.constants";
import GmsConfigureReportModal from "../gms-configure-report-modal/gms-configure-report-modal";

const sizeToClass = {
  [TableCellSize.SMALL]: "TableBlock--small",
  [TableCellSize.MEDIUM]: "TableBlock--medium",
  [TableCellSize.LARGE]: "TableBlock--large"
};

const alignToClass = {
  [TableHeaderCellAlignment.LEFT]: "TableBlock--left",
  [TableHeaderCellAlignment.CENTER]: "TableBlock--center",
  [TableHeaderCellAlignment.RIGHT]: "TableBlock--right"
};

@Component({
  components: {
    GmsConfigureReportModal,
    Table,
    Icon
  }
})
export default class TableBlock extends Vue {
  @Prop({
    type: String,
    default: ""
  })
  title;

  @Prop({
    type: Boolean,
    default: false
  })
  customizable;

  @Prop({
    type: Array,
    default: () => []
  })
  headers;

  @Prop({
    type: Array,
    default: () => []
  })
  rows;

  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues)
  })
  currency;

  @Prop({
    type: Boolean,
    default: true
  })
  showTotal;

  @Prop({
    type: String,
    default: TableBlockMode.GMS_RECONCILIATION,
    validator: has(TableBlockModeValues)
  })
  mode;

  @Prop({
    type: String,
    default: TableMode.DEFAUTL,
    validator: has(TableModeValues)
  })
  tableMode;

  @Prop({
    type: Boolean,
    default: true
  })
  hasBorder;

  CurrencyNotation = CurrencyNotation;
  IconShape = IconShape;
  TableDataType = TableDataType;
  TableBlockMode = TableBlockMode;
  TableMode = TableMode;
  amountBlockNumber = 0;
  showConfigureReport = false;
  currentHeaders = [];
  displayedHeaders = [];

  beforeMount() {
    this.headers.forEach(header => {
      const h = Object.assign({}, header);
      this.currentHeaders.push(h);
    });

    this.currentHeaders.sort((h1, h2) => {
      if (this.isAmount(h1.type) && !this.isAmount(h2.type)) return 1;
      else if (this.isAmount(h2.type) && !this.isAmount(h1.type)) return -1;
      return 0;
    });

    this.displayedHeaders = this.currentHeaders.filter(h => h.display);
    this.amountBlockNumber = this.displayedHeaders.filter(header =>
      this.isAmount(header.type)
    ).length;
  }

  get amountHeaders() {
    return this.headers.filter(header => this.isAmount(header.type));
  }

  get modeClass() {
    return this.mode;
  }

  getTotal(id) {
    let total = 0;
    this.rows.forEach(row => {
      total +=
        row.data[id].amount !== void 0 ? row.data[id].amount : row.data[id];
    });

    return currencyFormat(total);
  }

  getSizeClass(size) {
    return sizeToClass[size];
  }

  getAlignClass(align) {
    return alignToClass[align];
  }

  getBorderClass(index) {
    if (this.amountBlockNumber === 1) {
      return "TableBlock--only_child";
    }

    if (index === this.displayedHeaders.length - this.amountBlockNumber) {
      return "TableBlock--first_child";
    } else if (index === this.displayedHeaders.length - 1) {
      return "TableBlock--last_child";
    }

    return "TableBlock--middle_child";
  }

  isAmount(type) {
    return type === TableDataType.MONEY || type === TableDataType.NUMBER;
  }

  isLastEmpty(index) {
    return index === this.displayedHeaders.length - this.amountBlockNumber - 1;
  }

  handleCustomizeReport() {
    this.showConfigureReport = true;
  }

  handleCloseConfigureReport() {
    this.showConfigureReport = false;
  }

  handleApply(columns) {
    this.currentHeaders = columns;
    this.showConfigureReport = false;
    this.currentHeaders.sort((h1, h2) => {
      if (this.isAmount(h1.type) && !this.isAmount(h2.type)) return 1;
      else if (this.isAmount(h2.type) && !this.isAmount(h1.type)) return -1;
      return 0;
    });
    this.displayedHeaders = this.currentHeaders.filter(h => h.display);
    this.amountBlockNumber = this.displayedHeaders.filter(
      header => this.isAmount(header.type) && header.display
    ).length;

    /**
     * Apply new headers when users click apply button
     *
     * @event apply
     */
    this.$emit("apply", this.currentHeaders);
  }
}
</script>

<template>
  <div :class="['TableBlock', modeClass]">
    <div class="TableBlock__Header">
      <div class="TableBlock__Title">
        {{ title }}
      </div>
      <div
        v-if="customizable"
        class="TableBlock__Icon"
        @click="handleCustomizeReport"
      >
        <Icon :shape="IconShape.FRAME" :size="19" :color="'#2356f6'" />
      </div>
    </div>
    <Table
      class="TableBlock__Table"
      :mode="tableMode"
      :headers="currentHeaders"
      :rows="rows"
      :showControls="false"
      :stretch="true"
      :hasBorder="hasBorder"
    />
    <div v-if="showTotal" class="TableBlock__Total" :key="amountBlockNumber">
      <div class="TableBlock__TotalAmount">
        <div
          v-for="(item, i) in displayedHeaders"
          :key="i"
          :class="['TableBlock__Amount', getSizeClass(item.size)]"
        >
          <div
            v-if="isAmount(item.type)"
            :class="[
              'TableBlock__Sum',
              getAlignClass(item.align),
              getBorderClass(i)
            ]"
          >
            {{
              `${item.type === TableDataType.MONEY ? currency : ""}${getTotal(
                item.id
              )}`
            }}
          </div>
          <div v-else :class="['TableBlock__Empty']">
            {{ isLastEmpty(i) ? "Total" : "" }}
          </div>
        </div>
      </div>
    </div>
    <GmsConfigureReportModal
      v-if="showConfigureReport"
      :headers="currentHeaders"
      @apply="handleApply"
      @close="handleCloseConfigureReport"
    />
  </div>
</template>
